/**
 * This is the trigger gate for attestation. Source-state contract:
`reattest_required = true`, `reattest_completed_at IS NULL`, and
every leg owing a MAS cancel must have completed it. On success,
every disputed child whose latest operator-confirmed verdict is
Approved/Partial graduates from `not_required` to `pending`.

 * @summary Operator stamps that the group's MAS re-attest is complete
 */
export const CompleteGroupReattestParams = zod.object({
  id: zod.coerce.number(),
});

export const CompleteGroupReattestBody = zod.object({
  note: zod.string().nullish(),
  masReference: zod.string().nullish(),
  recordedOffline: zod
    .boolean()
    .optional()
    .describe(
      "Admin override. When true, bypass the macro-phase + cancel-completeness\npreconditions and stamp the same `reattestCompletedAt`\/`By` columns,\nrecording a distinct `mas_reattest_recorded_offline` audit row. Requires\nan admin actor and a non-empty `offlineNote` (>= 10 trimmed chars).\n",
    ),
  offlineNote: zod
    .string()
    .optional()
    .describe(
      "Required when `recordedOffline` is true. Free-form note (>= 10 trimmed\nchars) explaining when\/where the re-attest was recorded outside the\nstandard checklist.\n",
    ),
  renameInvoiceNumberTo: zod
    .string()
    .nullish()
    .describe(
      "Task #455 — when set, atomically rename the group's\n`invoiceNumber` from its current value to this trimmed value\ninside the same transaction as the re-attest stamp + draft\npromotion. Validates non-empty (after trim), differs from\ncurrent, and no other group already uses the same invoice\nnumber; otherwise the entire write rolls back with 409. A\ndistinct `group_invoice_number_renamed` audit row is written\nwith metadata `{from, to, sourceResponseId?}`.\n",
    ),
  renameSourceResponseId: zod
    .number()
    .nullish()
    .describe(
      "Optional `portal_responses.id` of the inbound payor reply that\ncited the new invoice number — recorded on the rename audit\nrow's metadata for traceability.\n",
    ),
});

