/**
 * Returns the live count of invoice groups in each of the seven
canonical macro phases (`pre-submit`, `in-flight`,
`response-pending`, `mas-action-required`, `awaiting-payout`,
`closed`, `on-hold`). One source of truth for the Dashboard
tiles, the Queue lane header, the sidebar MAS sub-badge, and
the Responses tabs — every consumer reuses
`buildMacroPhaseCondition` so the rollup, the Invoice Groups
list page (`?macroPhase=…`), the Queue lanes, and the Group
Detail header can never disagree about which bucket a row sits
in. (Task #559.)

 * @summary Per-macro-phase invoice group counts
 */
export const GetMacroPhaseRollupResponse = zod.object({
  counts: zod.object({
    preSubmit: zod
      .number()
      .describe(
        "Groups in the `pre-submit` macro phase (triage \/ ready-to-submit).",
      ),
    inFlight: zod
      .number()
      .describe(
        "Groups in the `in-flight` macro phase (submitted, awaiting first payor response).",
      ),
    responsePending: zod
      .number()
      .describe(
        "Groups in the `response-pending` macro phase (response received \/ under review).",
      ),
    masActionRequired: zod
      .number()
      .describe(
        "Groups in the `mas-action-required` macro phase (per-leg MAS cancels and\/or group re-attestation owed).",
      ),
    awaitingPayout: zod
      .number()
      .describe(
        "Groups in the transient `awaiting-payout` macro phase (re-attest recorded, payor not yet booked).",
      ),
    closed: zod
      .number()
      .describe(
        "Groups in the `closed` macro phase (final state — Resolved or Denied).",
      ),
    onHold: zod
      .number()
      .describe("Groups parked in the `on-hold` macro phase (status=On Hold)."),
    attestationOpen: zod
      .number()
      .describe(
        "Open attestation work — Approved-family \/ MAS-Eligible legs in\n`attestation_state ∈ {pending, queued}`. Drives the Attestation\ntab badge on the Responses Awaiting Review workspace so all\nthree tabs read counts from the same rollup endpoint\n(Task #560).\n",
      ),
  }),
});

/**
 * Returns the live count of invoice groups visible on the
`/responses-awaiting-review` page — i.e., groups in the
`response-pending` macro phase (status ∈ {Ready to Review,
Needs Review}) that have an Error Type assigned and are NOT in
the MAS-action-required state (those have moved to the
Attestation Queue). Drives the sidebar nav badge so the rail
and the page can never disagree. The same payload also carries
a `masActionCount` so the sidebar can render a sub-pill without
a second poll.

 * @summary Count of invoice groups whose payor response needs a verdict
 */
export const GetResponsesAwaitingReviewCountResponse = zod.object({
  count: zod
    .number()
    .describe(
      "Number of invoice groups visible on the Responses Awaiting\nReview page — `response-pending` macro phase (status ∈\n{Ready to Review, Needs Review}), Error Type assigned, NOT in\nMAS-action-required state, and with at least one reviewable\npayor response on file. Drives the sidebar nav badge.\n",
    ),
  masActionCount: zod
    .number()
    .describe(
      "Number of invoice groups whose macro phase is\n`mas-action-required` — i.e., per-leg verdicts are confirmed and\nthe operator still owes per-leg cancellations and\/or a group\nre-attestation. Surfaced as the sub-pill on the same nav badge\nso MAS work-in-flight is visible without a separate top-level\nentry.\n",
    ),
});

/**
 * Returns counts for groups that satisfy the base "response-pending"
criteria (status ∈ {Ready to Review, Needs Review}, no
re-attestation in flight, no MAS cancel pending) but are excluded
from the Responses Awaiting Review inbox by exactly one of:
  * `unclassified` — no error type assigned (would otherwise show)
  * `awaitingPayorAgain` — operator clicked "I replied — wait
    for payor again" and no newer response has arrived since
  * `acknowledgmentOnly` — every response on file has been
    (re)classified to `acknowledgment` / `abstain` so nothing
    is reviewable
Buckets are mutually exclusive, in the order above ("missing
error type wins" tie-breaker), so each hidden group is counted
at most once. Drives the "what's hidden" summary strip at the
top of the inbox.

 * @summary Counts of groups hidden from the Responses Awaiting Review inbox
 */
export const GetResponsesAwaitingReviewHiddenCountsResponse = zod.object({
  unclassified: zod
    .number()
    .describe(
      "Groups that satisfy the response-pending base criteria but\nhave no error type assigned. Click target: the classification\nqueue (filtered list of `__unassigned__` response-pending\ngroups).\n",
    ),
  awaitingPayorAgain: zod
    .number()
    .describe(
      'Groups suppressed by the operator\'s \"I replied — wait for\npayor again\" flip (no newer response since the stamp).\nExcludes groups already counted under `unclassified`.\n',
    ),
  acknowledgmentOnly: zod
    .number()
    .describe(
      "Groups whose every portal_response has been (re)classified\nas `acknowledgment` \/ `abstain`, leaving nothing reviewable.\nExcludes groups already counted under `unclassified` or\n`awaitingPayorAgain`.\n",
    ),
});

/**
 * Pairs every `ai_suggested` verdict in the window with the next
`operator_confirmed` verdict on the same leg, then rolls them up
per error type. Drives the calibration line under the AI suggestion
in `<PerLegVerdictPicker>`. Returns zeros when the error type has
no history yet — the UI renders "Not enough history yet" rather
than misleading 0% stats.

 * @summary AI vs operator agreement stats for one error type
 */
export const getAiCalibrationQueryWindowDaysMax = 365;

export const GetAiCalibrationQueryParams = zod.object({
  errorTypeId: zod.coerce.string(),
  windowDays: zod.coerce
    .number()
    .min(1)
    .max(getAiCalibrationQueryWindowDaysMax)
    .optional(),
});

export const GetAiCalibrationResponse = zod.object({
  errorTypeId: zod.string(),
  totalConfirmations: zod
    .number()
    .describe(
      "Number of paired (AI suggestion → operator confirmation) verdicts in the window.",
    ),
  agreementCount: zod.number().describe("How many of those pairs agreed."),
  perOutcomeAgreement: zod.object({
    Approved: zod.number(),
    Denied: zod.number(),
    Partial: zod.number(),
  }),
  windowDays: zod
    .number()
    .describe(
      "Window applied when computing the stats (defaults to 90 days server-side).",
    ),
});

