/**
 * @summary Generate a draft portal submission for review before queuing
 */
export const GeneratePortalSubmissionPreviewBody = zod.object({
  invoiceGroupId: zod.number().optional(),
  issueType: zod.string().optional(),
  subject: zod.string().optional(),
  requesterEmail: zod.string().optional(),
  transportationProviderName: zod.string().optional(),
  phoneNumber: zod.string().optional(),
  invoiceNumber: zod.string().optional(),
  gpsBreadcrumbsAvailable: zod.string().optional(),
  descriptionHtml: zod.string().optional(),
  disputeReason: zod.string().optional(),
  specialCircumstances: zod
    .string()
    .optional()
    .describe(
      "Optional narrative-changing context provided by the operator. If non-empty, `understandingReadback` MUST also be supplied (the UI gates Generate behind a confirmed AI readback).",
    ),
  understandingReadback: zod
    .string()
    .optional()
    .describe(
      "The 2–4 sentence AI readback the operator confirmed before generating the draft. Required when `specialCircumstances` is non-empty.",
    ),
  actorType: zod
    .enum(["operator", "system"])
    .optional()
    .describe(
      'Submission actor path. \"operator\" (default for human users) enforces all four readiness gates. \"system\" requires a valid bot service token and bypasses the readback and preview gates.',
    ),
  ack: zod
    .boolean()
    .optional()
    .describe(
      "Task #703 — bypass acknowledgement for lint \*\*warnings\*\* (not failures).\nPOST \/portal-submissions runs `lintDraft` on the prospective row before\ninsert. Hard `fail` results always 422 with `{ failures: LintResult[] }`.\nSoft `warn` results 422 with the same shape unless the caller passes\n`ack: true` AND `bypassReason` (≥ 10 chars). When set, a dedicated\n`lint_warnings_bypassed` audit row is written before the insert.\n",
    ),
  bypassReason: zod
    .string()
    .optional()
    .describe(
      "Free-text justification for bypassing lint warnings. Required when\n`ack: true`; minimum 10 characters. Stored in the metadata of the\n`lint_warnings_bypassed` audit row so the audit trail names \*why\* the\noperator overrode the warning, not just \*that\* they did.\n",
    ),
});

